#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    if (n < 2) {
        cout << 0 << "\n";
        return 0;
    }
    set<long long> targets = {a[0] + a[1], a[n - 2] + a[n - 1], a[0] + a[n - 1]};
    int answer = 0;
    vector<vector<int>> dp(n, vector<int>(n));
    for (long long target : targets) {
        // dp[l][r]: most operations on a[l..r] with every pair summing to target
        for (auto &row : dp) fill(row.begin(), row.end(), 0);
        for (int length = 2; length <= n; length++)
            for (int left = 0; left + length <= n; left++) {
                int right = left + length - 1, best = 0;
                if (a[left] + a[left + 1] == target) best = max(best, 1 + (length > 2 ? dp[left + 2][right] : 0));
                if (a[right - 1] + a[right] == target) best = max(best, 1 + (length > 2 ? dp[left][right - 2] : 0));
                if (a[left] + a[right] == target) best = max(best, 1 + (length > 2 ? dp[left + 1][right - 1] : 0));
                dp[left][right] = best;
            }
        answer = max(answer, dp[0][n - 1]);
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n < 2) {
            System.out.println(0);
            return;
        }
        Set<Long> targets = new HashSet<>(List.of(a[0] + a[1], a[n - 2] + a[n - 1], a[0] + a[n - 1]));
        int answer = 0;
        int[][] dp = new int[n][n];
        for (long target : targets) {
            // dp[l][r]: most operations on a[l..r] with every pair summing to target
            for (int[] row : dp) Arrays.fill(row, 0);
            for (int length = 2; length <= n; length++)
                for (int left = 0; left + length <= n; left++) {
                    int right = left + length - 1, best = 0;
                    if (a[left] + a[left + 1] == target) best = Math.max(best, 1 + (length > 2 ? dp[left + 2][right] : 0));
                    if (a[right - 1] + a[right] == target) best = Math.max(best, 1 + (length > 2 ? dp[left][right - 2] : 0));
                    if (a[left] + a[right] == target) best = Math.max(best, 1 + (length > 2 ? dp[left + 1][right - 1] : 0));
                    dp[left][right] = best;
                }
            answer = Math.max(answer, dp[0][n - 1]);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a := make([]int, n)
	for i := range a {
		a[i] = next()
	}
	if n < 2 {
		fmt.Println(0)
		return
	}
	targets := map[int]bool{a[0] + a[1]: true, a[n-2] + a[n-1]: true, a[0] + a[n-1]: true}
	answer := 0
	dp := make([][]int, n)
	for i := range dp {
		dp[i] = make([]int, n)
	}
	sub := func(l, r, length int) int {
		if length > 2 {
			return dp[l][r]
		}
		return 0
	}
	for target := range targets {
		// dp[l][r]: most operations on a[l..r] with every pair summing to target
		for _, row := range dp {
			clear(row)
		}
		for length := 2; length <= n; length++ {
			for left := 0; left+length <= n; left++ {
				right, best := left+length-1, 0
				if a[left]+a[left+1] == target {
					best = max(best, 1+sub(left+2, right, length))
				}
				if a[right-1]+a[right] == target {
					best = max(best, 1+sub(left, right-2, length))
				}
				if a[left]+a[right] == target {
					best = max(best, 1+sub(left+1, right-1, length))
				}
				dp[left][right] = best
			}
		}
		answer = max(answer, dp[0][n-1])
	}
	fmt.Println(answer)
}
